            if (!java.util.Objects.equals(limit, null))
            {
                ((Map<String, Object>)request).put("maxLevel", limit);
            }
            Map<String, Object> response = (this.v3PublicGetOrderbook(this.extend(request, parameters))).join();
            //
            // }
            //     {
            //         "success": true,
            //         "timestamp": 1751620923344,
            //         "data": {
            //             "asks": [
            //                 {
            //                     "price": "108924.86",
            //                     "quantity": "0.032126"
